    /// The Common Vulnerabilities and Exposures (CVE) ID.
    public var cveId: String?
    /// A list of Common Weakness Enumeration (CWE) IDs.
    public var cweIds: [String]?
    /// A list of users receiving credit for their participation in the security advisory.
    public var credits: [RepositoryAdvisoryCreateCreditsItem]?
    /// The severity of the advisory. You must choose between setting this field or `cvss_vector_string`.
    public var severity: RepositoryAdvisoryCreateSeverity?
    /// The CVSS vector that calculates the severity of the advisory. You must choose between setting this field or
    /// `severity`.
    public var cvssVectorString: String?
    /// Whether to create a temporary private fork of the repository to collaborate on a fix.
    public var startPrivateFork: Bool?

    enum CodingKeys: String, CodingKey {
        case summary
        case description
        case vulnerabilities
        case cveId = "cve_id"
        case cweIds = "cwe_ids"
        case credits
        case severity
        case cvssVectorString = "cvss_vector_string"
        case startPrivateFork = "start_private_fork"
    }

    private init(sdkCopy value: Self) {
        self = value
    }
}
